class MyStack:
    def __init__(self):
        # Use collections.deque as the underlying queue
        self.q = deque()

    def push(self, x: int) -> None:
        # Add element to the queue
        self.q.append(x)
        # Rotate all previous elements to the back of the queue
        for _ in range(len(self.q) - 1):
            self.q.append(self.q.popleft())

    def pop(self) -> int:
        # Remove and return the front element of the queue
        if not self.q:
            return -1
        return self.q.popleft()

    def top(self) -> int:
        # Peek and return the front element of the queue
        if not self.q:
            return -1
        return self.q[0]

    def empty(self) -> bool:
        # Return true if queue length is 0
        return len(self.q) == 0

